using Contoso.Text;

namespace Contoso.Text.Tests;

[TestClass]
public sealed class StringFormatterTests
{
    private readonly StringFormatter _formatter = new();

    [TestMethod]
    public void FormatPhoneNumber_ReturnsCorrectFormat()
    {
        var result = _formatter.FormatPhoneNumber("1234567890");

        Assert.AreEqual("(123) 456-7890", result);
        Assert.StartsWith(result, "(");
        Assert.EndsWith(result, "7890");
    }

    [TestMethod]
    public void FormatPhoneNumber_StartsWithParenthesizedAreaCode()
    {
        var result = _formatter.FormatPhoneNumber("8005551234");

        Assert.StartsWith(result, "(800)");
    }

    [TestMethod]
    public void FormatPhoneNumber_EndsWithLastFourDigits()
    {
        var result = _formatter.FormatPhoneNumber("8005551234");

        Assert.EndsWith(result, "1234");
    }

    [TestMethod]
    public void FormatPhoneNumber_NullInput_Throws()
    {
        Assert.ThrowsExactly<ArgumentNullException>(() => _formatter.FormatPhoneNumber(null!));
    }

    [TestMethod]
    public void FormatPhoneNumber_WrongLength_Throws()
    {
        Assert.ThrowsExactly<ArgumentException>(() => _formatter.FormatPhoneNumber("123"));
    }

    [TestMethod]
    public void BuildGreeting_DefaultTitle_StartsWithDearMr()
    {
        var result = _formatter.BuildGreeting("Smith");

        Assert.StartsWith(result, "Dear Mr.");
    }

    [TestMethod]
    public void BuildGreeting_DefaultTitle_EndsWithComma()
    {
        var result = _formatter.BuildGreeting("Smith");

        Assert.EndsWith(result, "Smith,");
    }

    [TestMethod]
    public void BuildGreeting_CustomTitle_UsesProvidedTitle()
    {
        var result = _formatter.BuildGreeting("Johnson", "Dr.");

        Assert.StartsWith(result, "Dear Dr.");
        Assert.EndsWith(result, "Johnson,");
        Assert.AreEqual("Dear Dr. Johnson,", result);
    }

    [TestMethod]
    public void BuildGreeting_WhitespaceName_Throws()
    {
        Assert.ThrowsExactly<ArgumentException>(() => _formatter.BuildGreeting("   "));
    }

    [TestMethod]
    public void GenerateSlug_SimpleTitle_ReturnsLowercaseHyphenated()
    {
        var result = _formatter.GenerateSlug("Hello World");

        Assert.AreEqual("hello-world", result);
    }

    [TestMethod]
    public void GenerateSlug_ComplexTitle_StartsWithFirstWord()
    {
        var result = _formatter.GenerateSlug("My Great Blog Post!");

        Assert.StartsWith(result, "my");
        Assert.EndsWith(result, "post");
    }

    [TestMethod]
    public void GenerateSlug_SpecialCharacters_StripsNonAlphanumeric()
    {
        var result = _formatter.GenerateSlug("C# is Awesome!!!");

        Assert.StartsWith(result, "c");
        Assert.EndsWith(result, "awesome");
    }

    [TestMethod]
    public void GenerateSlug_WhitespaceInput_Throws()
    {
        Assert.ThrowsExactly<ArgumentException>(() => _formatter.GenerateSlug("   "));
    }

    [TestMethod]
    public void FormatCurrency_DefaultSymbol_StartsWithDollarSign()
    {
        var result = _formatter.FormatCurrency(19.99m);

        Assert.StartsWith(result, "$");
        Assert.AreEqual("$19.99", result);
    }

    [TestMethod]
    public void FormatCurrency_CustomSymbol_StartsWithSymbol()
    {
        var result = _formatter.FormatCurrency(100m, "€");

        Assert.StartsWith(result, "€");
        Assert.EndsWith(result, "100.00");
    }

    [TestMethod]
    public void FormatCurrency_ZeroAmount_FormatsWithTwoDecimals()
    {
        var result = _formatter.FormatCurrency(0m);

        Assert.EndsWith(result, "0.00");
    }

    [TestMethod]
    public void FormatCurrency_NegativeAmount_IncludesMinusSign()
    {
        var result = _formatter.FormatCurrency(-5.5m);

        Assert.AreEqual("$-5.50", result);
    }
}

